"""Unit tests for memcard.py (card images are generated by the tests)."""

import os
import struct
import sys
import tempfile
import unittest

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

import memcard  # noqa: E402

CARD_BYTES = 131072


def _card(entries=()):
    """entries: (block 1..15, state word, filename)."""
    data = bytearray(CARD_BYTES)
    data[0:2] = b"MC"
    for block in range(1, 16):
        struct.pack_into("<I", data, block * 0x80, 0xA0)
    for block, state, name in entries:
        struct.pack_into("<I", data, block * 0x80, state)
        raw = name.encode("ascii")
        data[block * 0x80 + 0x0A:block * 0x80 + 0x0A + len(raw)] = raw
    return bytes(data)


class MemcardTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.path = os.path.join(self.tmp.name, "card1.mcd")

    def tearDown(self):
        self.tmp.cleanup()

    def _write(self, data):
        with open(self.path, "wb") as fh:
            fh.write(data)

    def test_empty_card_has_no_saves(self):
        self._write(_card())
        self.assertEqual(memcard.saves(self.path), [])

    def test_one_save_found(self):
        self._write(_card([(1, 0x51, "BESLES-02470MOH00")]))
        self.assertEqual(memcard.saves(self.path), ["BESLES-02470MOH00"])

    def test_free_and_link_blocks_ignored(self):
        self._write(_card([(1, 0x51, "BESLES-02470MOH00"), (2, 0xA0, "OLD"), (3, 0x52, "")]))
        self.assertEqual(memcard.saves(self.path), ["BESLES-02470MOH00"])

    def test_unformatted_raises(self):
        self._write(bytes(CARD_BYTES))
        with self.assertRaises(ValueError):
            memcard.saves(self.path)

    def test_moh_saves_filters_by_serial(self):
        self._write(_card([(1, 0x51, "BASCUS-94163XYZ"), (4, 0x51, "BESLES-02470MOH00")]))
        self.assertEqual(memcard.moh_saves(self.path), ["BESLES-02470MOH00"])


class SaveNameTests(unittest.TestCase):
    """MOH names its save file <serial><player name><slot digit>, e.g. BESLES-02470PASCAL0."""

    def test_name_from_filename(self):
        self.assertEqual(memcard.save_name("BESLES-02470PASCAL0"), "PASCAL")

    def test_only_one_slot_digit_is_dropped(self):
        self.assertEqual(memcard.save_name("BESLES-02470AGENT71"), "AGENT7")

    def test_foreign_save_rejected(self):
        with self.assertRaises(ValueError):
            memcard.save_name("BASCUS-94163XYZ0")


if __name__ == "__main__":
    unittest.main()
